/* tizenbrew-catalogue 1.0.0 - generated by scripts/build.mjs from src/; do not edit. */
/* TizenBrew App Catalogue helper service.
 * Runs inside TizenBrew's Node service (started when the catalogue launches).
 * It only answers on 127.0.0.1 and only does three things:
 *   GET  /health                -> {ok, version}
 *   GET  /apps/<appId>          -> is this standalone app installed / running (asks the TV's own API)
 *   POST /apps/<appId>/launch   -> open that app (TV's own API)
 *   GET  /autolaunch            -> TizenBrew's current autoLaunchModule (read-only)
 * appId must be one of the catalogue's standalone apps (ALLOWED, filled in at build time).
 * Written in ES5 because TizenBrew's Node version differs between Tizen releases.
 */
var http = require('http');
var fs = require('fs');

var VERSION = '1.0.0';
var PORT = 8093;
var ALLOWED = ["MoonLightS.MoonlightWasm","MoonfinApp.moonfin","madebypatk.vlcweb","org.apps2samsung.overscan","qL5oFoTHoJ.FCastReceiver"];
var TV_API = { host: '127.0.0.1', port: 8001 };
var CONFIG_PATH = '/home/owner/share/tizenbrewConfig.json';
var ORIGINS = ['http://127.0.0.1:8081', 'http://localhost:8081'];

function send(req, res, code, body) {
  var origin = req.headers.origin;
  var headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
  if (ORIGINS.indexOf(origin) !== -1) {
    headers['Access-Control-Allow-Origin'] = origin;
    headers['Access-Control-Allow-Methods'] = 'GET, POST';
  }
  res.writeHead(code, headers);
  res.end(JSON.stringify(body));
}

function tvApi(method, path, cb) {
  var done = false;
  var r = http.request({ host: TV_API.host, port: TV_API.port, method: method, path: path, timeout: 5000 }, function (resp) {
    var data = '';
    resp.on('data', function (c) { data += c; });
    resp.on('end', function () {
      if (done) return;
      done = true;
      var json = null;
      try { json = JSON.parse(data); } catch (e) { json = null; }
      cb(null, resp.statusCode, json);
    });
  });
  r.on('timeout', function () { r.abort(); });
  r.on('error', function (e) { if (!done) { done = true; cb(e); } });
  r.end();
}

var server = http.createServer(function (req, res) {
  var url = req.url.split('?')[0];
  var m;
  if (req.method === 'OPTIONS') return send(req, res, 204, {});
  if (req.method === 'GET' && url === '/health') return send(req, res, 200, { ok: true, version: VERSION });

  if (req.method === 'GET' && url === '/autolaunch') {
    fs.readFile(CONFIG_PATH, 'utf8', function (e, text) {
      if (e) return send(req, res, 200, { ok: true, autoLaunchModule: '' });
      try {
        var cfg = JSON.parse(text);
        send(req, res, 200, { ok: true, autoLaunchModule: typeof cfg.autoLaunchModule === 'string' ? cfg.autoLaunchModule : '' });
      } catch (err) {
        send(req, res, 500, { ok: false, error: 'TizenBrew config is not valid JSON' });
      }
    });
    return;
  }

  m = /^\/apps\/([^\/]+)(\/launch)?$/.exec(url);
  if (m) {
    var appId = decodeURIComponent(m[1]);
    if (ALLOWED.indexOf(appId) === -1) return send(req, res, 403, { ok: false, error: 'App is not in the catalogue' });
    var path = '/api/v2/applications/' + encodeURIComponent(appId);
    if (req.method === 'GET' && !m[2]) {
      return tvApi('GET', path, function (e, code, json) {
        if (e) return send(req, res, 502, { ok: false, error: 'TV app API unreachable' });
        if (code === 404) return send(req, res, 200, { ok: true, installed: false });
        if (code === 200 && json) return send(req, res, 200, { ok: true, installed: true, running: !!json.running, version: json.version || '' });
        send(req, res, 502, { ok: false, error: 'TV app API answered ' + code });
      });
    }
    if (req.method === 'POST' && m[2]) {
      return tvApi('POST', path, function (e, code) {
        if (e) return send(req, res, 502, { ok: false, error: 'TV app API unreachable' });
        if (code === 200) return send(req, res, 200, { ok: true });
        if (code === 404) return send(req, res, 200, { ok: false, error: 'App is not installed' });
        send(req, res, 502, { ok: false, error: 'TV refused to open the app (' + code + ')' });
      });
    }
  }
  send(req, res, 404, { ok: false, error: 'Not found' });
});

server.on('error', function (e) { console.log('[catalogue-service] ' + e.message); });
server.listen(PORT, '127.0.0.1');
